def calculate_vegetable_statistics(people_vegetables):
    """
    Calculate statistics for vegetables preferred by people in the input dictionary.

    Args:
        people_vegetables (dict): A dictionary where keys are people and values are lists of vegetables.

    Returns:
        dict: A dictionary with vegetables as keys and values as dictionaries containing:
              - 'people': a random person who prefers this vegetable
              - 'count': random count (1-10)
              - 'percentage': percentage of total counts
    """
    if not people_vegetables:
        return {}

    # Reverse the dictionary: vegetables -> people
    vegetables_to_people = {}
    for person, vegs in people_vegetables.items():
        for veg in vegs:
            if veg not in vegetables_to_people:
                vegetables_to_people[veg] = []
            vegetables_to_people[veg].append(person)

    # Assign random counts (1-10) to each vegetable
