    # Create the result dictionary
    result = {}
    for veg in vegetables_to_people:
        # Randomly select a person who prefers this vegetable
        person = np.random.choice(vegetables_to_people[veg])
        result[veg] = {
            'people': person,
            'count': counts[veg],
