from typing import Optional, Union, Dict
import math

def excel_column_stats(
    file_path: str,
    column: Union[str, int],
    sheet: Optional[Union[str, int]] = 0
) -> Dict[str, Optional[float]]:
    """
    Read an Excel file column and compute mean, median, and standard deviation (sample std).
    Uses polars for reading and computing.

    Parameters:
    - file_path: path to the .xlsx file
    - column: column name (str) or zero-based column index (int)
    - sheet: sheet name or index (default 0, first sheet)

    Returns:
    - dict with keys 'mean', 'median', 'std' (values are floats or None if no numeric data)
    """
    try:
        import polars as pl
    except Exception as e:
        raise ImportError(
            "polars is required. Install with: pip install 'polars[all]' openpyxl"
        ) from e

    # Read Excel. polars provides read_excel; depending on version the parameter might be sheet_name or sheet_id.
    try:
        # preferred modern API
        df = pl.read_excel(file_path, sheet_name=sheet)
    except TypeError:
        # fallback if polars version uses sheet_id
        df = pl.read_excel(file_path, sheet_id=sheet)
    except AttributeError:
        # very old polars without read_excel: raise a clear error
        raise RuntimeError(
            "Your polars version does not support read_excel. "
            "Upgrade polars: pip install -U 'polars[all]'"
        )

    # Resolve column by index or name
    if isinstance(column, int):
        try:
            col_name = df.columns[column]
        except Exception:
            raise IndexError(f"Column index {column} out of range for sheet with columns {df.columns}")
    else:
        col_name = column
        if col_name not in df.columns:
            raise KeyError(f"Column '{col_name}' not found. Available columns: {df.columns}")

    # Extract series, drop nulls, and coerce to float where possible
    series = df[col_name].drop_nulls()

    # If the series is empty, return None for stats
    if series.is_empty():
        return {"mean": None, "median": None, "std": None}

    # Try to cast to Float64. Non-numeric entries will become null and can be dropped.
    try:
        series = series.cast(pl.Float64)
    except Exception:
        # If cast fails for some reason, attempt elementwise filtering below
        pass

    # Convert to Python list and filter numeric finite values (floats and ints)
    values = []
    for v in series.to_list():
        # polars may produce None for non-castable items
        if v is None:
            continue
        # Keep only finite numbers
        try:
            if isinstance(v, (int, float)) and math.isfinite(v):
                values.append(float(v))
        except Exception:
            continue

    if not values:
        return {"mean": None, "median": None, "std": None}

    # Compute stats using simple formulas (sample std, ddof=1)
    n = len(values)
    mean = sum(values) / n

    sorted_vals = sorted(values)
    # median
    if n % 2 == 1:
        median = float(sorted_vals[n // 2])
    else:
        median = float((sorted_vals[n // 2 - 1] + sorted_vals[n // 2]) / 2)

    # sample standard deviation: sqrt( sum((x-mean)^2) / (n-1) ) if n>1, else std=None
    if n > 1:
        var = sum((x - mean) ** 2 for x in values) / (n - 1)
        std = math.sqrt(var)
    else:
        std = 0.0  # with a single value, std is often defined as 0.0; change to None if preferred

    return {"mean": float(mean), "median": float(median), "std": float(std)}
```

