```python
from typing import Any
import unicodedata

import httpx
from pydantic import BaseModel


class GitHubUser(BaseModel):
    # Accept any fields returned by the API (we list no explicit fields to keep it generic)
    model_config = {"extra": "allow"}


def fetch_github_user_ascii(username: str, timeout: float = 10.0) -> dict[str, Any]:
    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary of the normalized data.

    Uses httpx for the HTTP request and pydantic v2 for a lenient model parsing
    (pydantic v2 was released in 2023).

    Raises:
      ValueError: if username is empty or the user is not found (HTTP 404).
      RuntimeError: for other HTTP errors or network problems.

    Example:
      result = fetch_github_user_ascii("octocat")
    """
    if not isinstance(username, str) or not username.strip():
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{username}"
    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "fetch_github_user_ascii/1.0",
    }

    try:
        resp = httpx.get(url, headers=headers, timeout=timeout)
    except httpx.RequestError as exc:
        raise RuntimeError(f"Network error while requesting GitHub API: {exc}") from exc

    if resp.status_code == 404:
        raise ValueError(f"GitHub user '{username}' not found (404).")
    if resp.status_code != 200:
        raise RuntimeError(f"GitHub API returned status {resp.status_code}: {resp.text}")

    try:
        data = resp.json()
    except ValueError as exc:
        raise RuntimeError("Failed to parse JSON response from GitHub API") from exc

    # Validate/accept the data with pydantic (lenient model that allows extra fields)
    user = GitHubUser.model_validate(data)
    raw_dict = user.model_dump()  # dict with the parsed data

    def normalize(value: Any) -> Any:
        """Recursively normalize strings to ASCII; normalize dict keys too."""
        if isinstance(value, str):
            # Normalize to NFKD and drop non-ASCII
            nfkd = unicodedata.normalize("NFKD", value)
            return nfkd.encode("ascii", "ignore").decode("ascii")
        elif isinstance(value, dict):
            new_dict: dict[Any, Any] = {}
            for k, v in value.items():
                # Normalize keys if they are strings
                new_key = normalize(k) if isinstance(k, str) else k
                new_dict[new_key] = normalize(v)
            return new_dict
        elif isinstance(value, list):
            return [normalize(item) for item in value]
        else:
            return value

    normalized = normalize(raw_dict)
    return normalized
