from collections import Counter
from typing import Any, Dict, Iterable
from pydantic import BaseModel


class XYZItem(BaseModel):
    x: Any | None = None
    y: Any | None = None
    z: Any | None = None


def _make_hashable(val: Any) -> Any:
    """Return a hashable representation for val (use repr for unhashable objects)."""
    try:
        hash(val)
        return val
    except Exception:
        return repr(val)


def count_xyz(d: Iterable[dict]) -> Dict[str, Dict[Any, int]]:
    """
    Count occurrences of values under keys "x", "y", and "z" from a list/iterable of dicts.

    Args:
        d: iterable of dictionaries (each may or may not contain x, y, z)

    Returns:
        A dict with keys 'x','y','z' mapping to dicts of value->count.
    """
    counters = {"x": Counter(), "y": Counter(), "z": Counter()}

    for entry in d:
        try:
            item = XYZItem.model_validate(entry)  # pydantic v2 validation
        except Exception:
            # Skip entries that can't be validated as mappings/dicts
            continue

        for key in ("x", "y", "z"):
            val = getattr(item, key)
            if val is None:
                continue
            counters[key][_make_hashable(val)] += 1

    # Convert Counters to plain dicts for easier use/serialization
    return {k: dict(v) for k, v in counters.items()}


# Example usage:
if __name__ == "__main__":
    d = [
        {"x": 1, "y": "a"},
        {"x": 1, "z": [1, 2]},
        {"y": "a", "z": [1, 2]},
        {"x": 2, "y": None},
        {"x": {"sub": 1}},  # unhashable -> will be counted by repr
    ]

    counts = count_xyz(d)
    print(counts)
    # Example output:
    # {
    #   'x': {1: 2, 2: 1, "{'sub': 1}": 1},
    #   'y': {'a': 2},
    #   'z': {'[1, 2]': 2}
    # }
```

